package com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer;

enum MunicipalitySizeGroup {
    GROUP_1,
    GROUP_2,
    GROUP_3,
    GROUP_4;

    static MunicipalitySizeGroup fromPopulation(int population) {
        if (population <= 20_000) {
            return GROUP_1;
        }
        if (population <= 100_000) {
            return GROUP_2;
        }
        if (population <= 1_000_000) {
            return GROUP_3;
        }
        return GROUP_4;
    }
}

