        return GROUP_4;
    }
}

package com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer;

import com.diegoramos.konatus.pesquisaeleitoral.domain.Candidate;
import com.diegoramos.konatus.pesquisaeleitoral.domain.Municipality;
import com.diegoramos.konatus.pesquisaeleitoral.domain.Poll;
import com.diegoramos.konatus.pesquisaeleitoral.domain.PollResult;
import com.diegoramos.konatus.pesquisaeleitoral.domain.State;
import com.diegoramos.konatus.pesquisaeleitoral.exceptions.BusinessException;
import com.diegoramos.konatus.pesquisaeleitoral.repository.MunicipalityRepository;
import com.diegoramos.konatus.pesquisaeleitoral.repository.PollRepository;
import com.diegoramos.konatus.pesquisaeleitoral.repository.PollResultRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

@Service
@RequiredArgsConstructor
public class PollImportService {

    private final PollCsvParser pollCsvParser;
    private final PollReferenceResolver pollReferenceResolver;
    private final MunicipalityRepository municipalityRepository;
    private final PollRepository pollRepository;
    private final PollResultRepository pollResultRepository;

    @Transactional
    public PollImportResult researchImport(MultipartFile archive) {
        List<ResearchLine> linhas = pollCsvParser.parse(archive);
        if (linhas.isEmpty()) {
            throw new BusinessException("Arquivo CSV sem linhas de dados");
        }

        String pollId = linhas.getFirst().pollId();
        LocalDate pollDate = linhas.getFirst().pollDate();

        validateSamePollMetadata(linhas, pollId, pollDate);

        Poll poll = pollRepository.findByNameAndPollDate(pollId, pollDate)
                .orElseGet(() -> pollRepository.save(Poll.create(pollId, pollDate)));

        PollWeightAccumulator weightAccumulator = new PollWeightAccumulator();
        Map<UUID, Candidate> candidatesById = new HashMap<>();
        Map<UUID, Boolean> populatedStates = new HashMap<>();

        for (ResearchLine linha : linhas) {
            processResearchLine(linha, poll, weightAccumulator, candidatesById, populatedStates);
        }

        long totalPopulation = weightAccumulator.totalPopulation();
        if (totalPopulation <= 0) {
            throw new BusinessException("Nao foi possivel calcular ponderacao: populacao dos municipios esta zerada");
        }

        List<CandidateWeightedResult> weightedResults = weightAccumulator.buildResults(totalPopulation);

        weightedResults.sort(Comparator.comparing(CandidateWeightedResult::weightedPercentage).reversed());

        return new PollImportResult(pollId, pollDate, totalPopulation, weightedResults);
    }

    private void processResearchLine(
            ResearchLine line,
            Poll poll,
            PollWeightAccumulator weightAccumulator,
            Map<UUID, Candidate> candidatesById,
            Map<UUID, Boolean> populatedStates
    ) {
        State state = pollReferenceResolver.resolveState(line.state());
        Municipality municipality = pollReferenceResolver.resolveMunicipality(line.municipality(), state);
        Candidate candidate = resolveCandidateCached(line.candidateId(), candidatesById);

        if (!populatedStates.containsKey(state.getId())) {
            weightAccumulator.registerStateMunicipalities(state, municipalityRepository.findAllByState(state));
            populatedStates.put(state.getId(), true);
        }

        pollResultRepository.save(PollResult.create(poll, municipality, candidate, line.percentual()));
        weightAccumulator.addSample(state, municipality, candidate, line.percentual());
    }

    private Candidate resolveCandidateCached(UUID candidateId, Map<UUID, Candidate> candidatesById) {
        return candidatesById.computeIfAbsent(
                candidateId,
                pollReferenceResolver::resolveCandidate
        );
    }

    private void validateSamePollMetadata(List<ResearchLine> linhas, String pollId, LocalDate pollDate) {
        for (ResearchLine linha : linhas) {
            if (!pollId.equals(linha.pollId()) || !pollDate.equals(linha.pollDate())) {
                throw new BusinessException("Arquivo deve conter apenas uma pesquisa por importacao");
            }
        }
    }
}

package com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer;

import com.diegoramos.konatus.pesquisaeleitoral.domain.Candidate;
import com.diegoramos.konatus.pesquisaeleitoral.domain.Municipality;
import com.diegoramos.konatus.pesquisaeleitoral.domain.Poll;
import com.diegoramos.konatus.pesquisaeleitoral.domain.PollResult;
import com.diegoramos.konatus.pesquisaeleitoral.domain.State;
import com.diegoramos.konatus.pesquisaeleitoral.exceptions.BusinessException;
import com.diegoramos.konatus.pesquisaeleitoral.repository.MunicipalityRepository;
import com.diegoramos.konatus.pesquisaeleitoral.repository.PollRepository;
import com.diegoramos.konatus.pesquisaeleitoral.repository.PollResultRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

@Service
@RequiredArgsConstructor
public class PollImportService {

    private final PollCsvParser pollCsvParser;
    private final PollReferenceResolver pollReferenceResolver;
    private final MunicipalityRepository municipalityRepository;
    private final PollRepository pollRepository;
    private final PollResultRepository pollResultRepository;

    @Transactional
    public PollImportResult researchImport(MultipartFile archive) {
        List<ResearchLine> linhas = pollCsvParser.parse(archive);
        if (linhas.isEmpty()) {
            throw new BusinessException("Arquivo CSV sem linhas de dados");
        }

        String pollId = linhas.getFirst().pollId();
        LocalDate pollDate = linhas.getFirst().pollDate();

        validateSamePollMetadata(linhas, pollId, pollDate);

        Poll poll = pollRepository.findByNameAndPollDate(pollId, pollDate)
                .orElseGet(() -> pollRepository.save(Poll.create(pollId, pollDate)));

        PollWeightAccumulator weightAccumulator = new PollWeightAccumulator();
        Map<UUID, Candidate> candidatesById = new HashMap<>();
        Map<UUID, Boolean> populatedStates = new HashMap<>();

        for (ResearchLine linha : linhas) {
            processResearchLine(linha, poll, weightAccumulator, candidatesById, populatedStates);
        }

        long totalPopulation = weightAccumulator.totalPopulation();
        if (totalPopulation <= 0) {
            throw new BusinessException("Nao foi possivel calcular ponderacao: populacao dos municipios esta zerada");
        }

        List<CandidateWeightedResult> weightedResults = weightAccumulator.buildResults(totalPopulation);
        List<PollGroupBreakdown> groupBreakdown = weightAccumulator.buildGroupBreakdown();

        weightedResults.sort(Comparator.comparing(CandidateWeightedResult::weightedPercentage).reversed());

        return new PollImportResult(pollId, pollDate, totalPopulation, weightedResults, groupBreakdown);
    }

    private void processResearchLine(
            ResearchLine line,
            Poll poll,
            PollWeightAccumulator weightAccumulator,
            Map<UUID, Candidate> candidatesById,
            Map<UUID, Boolean> populatedStates
    ) {
        State state = pollReferenceResolver.resolveState(line.state());
        Municipality municipality = pollReferenceResolver.resolveMunicipality(line.municipality(), state);
        Candidate candidate = resolveCandidateCached(line.candidateId(), candidatesById);

        if (!populatedStates.containsKey(state.getId())) {
            weightAccumulator.registerStateMunicipalities(state, municipalityRepository.findAllByState(state));
            populatedStates.put(state.getId(), true);
        }

        pollResultRepository.save(PollResult.create(poll, municipality, candidate, line.percentual()));
        weightAccumulator.addSample(state, municipality, candidate, line.percentual());
    }

    private Candidate resolveCandidateCached(UUID candidateId, Map<UUID, Candidate> candidatesById) {
        return candidatesById.computeIfAbsent(
                candidateId,
                pollReferenceResolver::resolveCandidate
        );
    }

    private void validateSamePollMetadata(List<ResearchLine> linhas, String pollId, LocalDate pollDate) {
        for (ResearchLine linha : linhas) {
            if (!pollId.equals(linha.pollId()) || !pollDate.equals(linha.pollDate())) {
                throw new BusinessException("Arquivo deve conter apenas uma pesquisa por importacao");
            }
        }
    }
}

package com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer;

import com.diegoramos.konatus.pesquisaeleitoral.domain.Candidate;
import com.diegoramos.konatus.pesquisaeleitoral.domain.Municipality;
import com.diegoramos.konatus.pesquisaeleitoral.domain.State;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.UUID;

class PollWeightAccumulator {

    private static final BigDecimal ONE_HUNDRED = new BigDecimal("100");

    private final Map<UUID, BigDecimal> weightedCandidateVotes = new HashMap<>();
    private final Map<UUID, String> candidateNames = new HashMap<>();
    private final Map<String, Integer> uniqueMunicipalityPopulation = new HashMap<>();

    void add(State state, Municipality municipality, Candidate candidate, BigDecimal percentage) {
        String municipalityKey = state.getId() + ":" + municipality.getId();
        uniqueMunicipalityPopulation.putIfAbsent(municipalityKey, municipality.getPopulation());

        BigDecimal weightedValue = percentage
                .multiply(BigDecimal.valueOf(municipality.getPopulation()))
                .divide(ONE_HUNDRED, 8, RoundingMode.HALF_UP);

        weightedCandidateVotes.merge(candidate.getId(), weightedValue, BigDecimal::add);
        candidateNames.putIfAbsent(candidate.getId(), candidate.getName());
    }

    long totalPopulation() {
        return uniqueMunicipalityPopulation.values().stream().mapToLong(Integer::longValue).sum();
    }

    List<CandidateWeightedResult> buildResults(long totalPopulation) {
        List<CandidateWeightedResult> weightedResults = new ArrayList<>();

        for (Map.Entry<UUID, BigDecimal> entry : weightedCandidateVotes.entrySet()) {
            BigDecimal result = entry.getValue()
                    .divide(BigDecimal.valueOf(totalPopulation), 8, RoundingMode.HALF_UP)
                    .multiply(ONE_HUNDRED)
                    .setScale(2, RoundingMode.HALF_UP);

            String candidateName = candidateNames.getOrDefault(entry.getKey(), "Candidato sem nome");
            weightedResults.add(new CandidateWeightedResult(entry.getKey(), candidateName, result));
        }

        return weightedResults;
    }
}

package com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer;

import com.diegoramos.konatus.pesquisaeleitoral.domain.Candidate;
import com.diegoramos.konatus.pesquisaeleitoral.domain.Municipality;
import com.diegoramos.konatus.pesquisaeleitoral.domain.State;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.UUID;

class PollWeightAccumulator {

    private static final BigDecimal ONE_HUNDRED = new BigDecimal("100");

    private final Map<UUID, BigDecimal> projectedCandidateVotes = new HashMap<>();
    private final Map<UUID, String> candidateNames = new HashMap<>();
    private final Map<GroupRegionKey, Long> regionTotalPopulation = new HashMap<>();
    private final Map<GroupRegionKey, Long> regionSamplePopulation = new HashMap<>();
    private final Map<GroupRegionKey, Map<UUID, BigDecimal>> regionSampleWeightedVotes = new HashMap<>();
    private final Map<GroupRegionKey, Map<UUID, String>> regionSampleCandidateNames = new HashMap<>();
    private final Map<GroupRegionKey, Map<UUID, Integer>> seenMunicipalities = new HashMap<>();
    private final Map<GroupRegionKey, String> regionStateAcronyms = new HashMap<>();
    private final Map<GroupRegionKey, Map<UUID, BigDecimal>> regionProjectedCandidatePercentages = new HashMap<>();

    void registerStateMunicipalities(State state, Collection<Municipality> municipalities) {
        Map<MunicipalitySizeGroup, Long> groupedPopulation = new HashMap<>();

        for (Municipality municipality : municipalities) {
            MunicipalitySizeGroup group = MunicipalitySizeGroup.fromPopulation(municipality.getPopulation());
            groupedPopulation.merge(group, (long) municipality.getPopulation(), Long::sum);
        }

        for (Map.Entry<MunicipalitySizeGroup, Long> entry : groupedPopulation.entrySet()) {
            GroupRegionKey key = GroupRegionKey.of(state, entry.getKey());
            regionTotalPopulation.put(key, entry.getValue());
            regionStateAcronyms.put(key, state.getStateAcronym());
        }
    }

    void addSample(State state, Municipality municipality, Candidate candidate, BigDecimal percentage) {
        GroupRegionKey key = GroupRegionKey.of(state, MunicipalitySizeGroup.fromPopulation(municipality.getPopulation()));

        Map<UUID, Integer> municipalitiesByCandidate = seenMunicipalities.computeIfAbsent(key, ignored -> new HashMap<>());
        municipalitiesByCandidate.putIfAbsent(municipality.getId(), municipality.getPopulation());
        long samplePopulation = municipalitiesByCandidate.values().stream().mapToLong(Integer::longValue).sum();
        regionSamplePopulation.put(key, samplePopulation);

        BigDecimal weightedValue = percentage
                .multiply(BigDecimal.valueOf(municipality.getPopulation()))
                .divide(ONE_HUNDRED, 8, RoundingMode.HALF_UP);

        regionSampleWeightedVotes
                .computeIfAbsent(key, ignored -> new HashMap<>())
                .merge(candidate.getId(), weightedValue, BigDecimal::add);

        regionSampleCandidateNames
                .computeIfAbsent(key, ignored -> new HashMap<>())
                .putIfAbsent(candidate.getId(), candidate.getName());

        candidateNames.putIfAbsent(candidate.getId(), candidate.getName());
    }

    long totalPopulation() {
        return regionTotalPopulation.values().stream().mapToLong(Long::longValue).sum();
    }

    List<CandidateWeightedResult> buildResults(long totalPopulation) {
        projectVotesByRegion();

        List<CandidateWeightedResult> weightedResults = new ArrayList<>();

        for (Map.Entry<UUID, BigDecimal> entry : projectedCandidateVotes.entrySet()) {
            BigDecimal result = entry.getValue()
                    .divide(BigDecimal.valueOf(totalPopulation), 8, RoundingMode.HALF_UP)
                    .multiply(ONE_HUNDRED)
                    .setScale(2, RoundingMode.HALF_UP);

            String candidateName = candidateNames.getOrDefault(entry.getKey(), "Candidato sem nome");
            weightedResults.add(new CandidateWeightedResult(entry.getKey(), candidateName, result));
        }

        return weightedResults;
    }

    List<PollGroupBreakdown> buildGroupBreakdown() {
        List<PollGroupBreakdown> result = new ArrayList<>();

        for (Map.Entry<GroupRegionKey, Map<UUID, BigDecimal>> regionEntry : regionProjectedCandidatePercentages.entrySet()) {
            GroupRegionKey region = regionEntry.getKey();
            List<GroupCandidateWeightedResult> candidates = regionEntry.getValue().entrySet().stream()
                    .map(entry -> new GroupCandidateWeightedResult(
                            entry.getKey(),
                            candidateNames.getOrDefault(entry.getKey(), "Candidato sem nome"),
                            entry.getValue().setScale(2, RoundingMode.HALF_UP)
                    ))
                    .sorted(Comparator.comparing(GroupCandidateWeightedResult::weightedPercentage).reversed())
                    .toList();

            result.add(new PollGroupBreakdown(
                    regionStateAcronyms.getOrDefault(region, "?"),
                    region.group(),
                    regionTotalPopulation.getOrDefault(region, 0L),
                    regionSamplePopulation.getOrDefault(region, 0L),
                    candidates
            ));
        }

        result.sort(Comparator
                .comparing(PollGroupBreakdown::stateAcronym)
                .thenComparing(item -> item.municipalityGroup().ordinal()));
        return result;
    }

    private void projectVotesByRegion() {
        projectedCandidateVotes.clear();
        regionProjectedCandidatePercentages.clear();

        for (Map.Entry<GroupRegionKey, Map<UUID, BigDecimal>> regionEntry : regionSampleWeightedVotes.entrySet()) {
            GroupRegionKey region = regionEntry.getKey();
            long samplePopulation = regionSamplePopulation.getOrDefault(region, 0L);
            long regionPopulation = regionTotalPopulation.getOrDefault(region, samplePopulation);

            if (samplePopulation <= 0 || regionPopulation <= 0) {
                continue;
            }

            for (Map.Entry<UUID, BigDecimal> candidateEntry : regionEntry.getValue().entrySet()) {
                BigDecimal samplePercentage = candidateEntry.getValue()
                        .divide(BigDecimal.valueOf(samplePopulation), 8, RoundingMode.HALF_UP)
                        .multiply(ONE_HUNDRED);

                regionProjectedCandidatePercentages
                        .computeIfAbsent(region, ignored -> new HashMap<>())
                        .put(candidateEntry.getKey(), samplePercentage);

                BigDecimal projectedVotes = samplePercentage
                        .multiply(BigDecimal.valueOf(regionPopulation))
                        .divide(ONE_HUNDRED, 8, RoundingMode.HALF_UP);

                projectedCandidateVotes.merge(candidateEntry.getKey(), projectedVotes, BigDecimal::add);

                String sampledName = regionSampleCandidateNames
                        .getOrDefault(region, Map.of())
                        .get(candidateEntry.getKey());
                if (sampledName != null) {
                    candidateNames.putIfAbsent(candidateEntry.getKey(), sampledName);
                }
            }
        }
    }

    private record GroupRegionKey(UUID stateId, MunicipalitySizeGroup group) {
        static GroupRegionKey of(State state, MunicipalitySizeGroup group) {
            return new GroupRegionKey(state.getId(), group);
        }
    }
}

package com.diegoramos.konatus.pesquisaeleitoral.controller;

import com.diegoramos.konatus.pesquisaeleitoral.dto.candidateDTO.CandidateWeightedResultDTO;
import com.diegoramos.konatus.pesquisaeleitoral.dto.pollDTO.PollImportMapper;
import com.diegoramos.konatus.pesquisaeleitoral.dto.pollDTO.PollImportResponseDTO;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.CandidateWeightedResult;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.PollImportResult;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.PollImportService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.web.servlet.MockMvc;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.BDDMockito.given;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(PollImportController.class)
class PollImportControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private PollImportService pollImportService;

    @MockBean
    private PollImportMapper pollImportMapper;

    @Test
    void shouldImportPollCsvAndReturnWeightedCandidates() throws Exception {
        UUID candidateId = UUID.randomUUID();
        PollImportResult result = new PollImportResult(
                "PESQ-2026-01",
                LocalDate.of(2026, 3, 1),
                1000000L,
                List.of(new CandidateWeightedResult(candidateId, "Maria Silva", new BigDecimal("42.35")))
        );
        PollImportResponseDTO response = new PollImportResponseDTO(
                "PESQ-2026-01",
                LocalDate.of(2026, 3, 1),
                1000000L,
                List.of(new CandidateWeightedResultDTO(
                        candidateId,
                        "Maria Silva",
                        new BigDecimal("42.35")
                ))
        );

        given(pollImportService.researchImport(any())).willReturn(result);
        given(pollImportMapper.toResponse(result)).willReturn(response);

        MockMultipartFile file = new MockMultipartFile(
                "file",
                "pesquisa.csv",
                "text/csv",
                "poll_id,poll_date,estado,municipio,candidate_id,percentual".getBytes()
        );

        mockMvc.perform(multipart("/api/polls/import").file(file))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.pollId").value("PESQ-2026-01"))
                .andExpect(jsonPath("$.weightedPopulation").value(1000000L))
                .andExpect(jsonPath("$.candidates[0].candidateId").value(candidateId.toString()))
                .andExpect(jsonPath("$.candidates[0].candidateName").value("Maria Silva"))
                .andExpect(jsonPath("$.candidates[0].weightedPercentage").value(42.35));
    }
}

package com.diegoramos.konatus.pesquisaeleitoral.controller;

import com.diegoramos.konatus.pesquisaeleitoral.dto.candidateDTO.CandidateWeightedResultDTO;
import com.diegoramos.konatus.pesquisaeleitoral.dto.candidateDTO.GroupCandidateWeightedResultDTO;
import com.diegoramos.konatus.pesquisaeleitoral.dto.pollDTO.PollImportMapper;
import com.diegoramos.konatus.pesquisaeleitoral.dto.pollDTO.PollImportResponseDTO;
import com.diegoramos.konatus.pesquisaeleitoral.dto.pollDTO.PollGroupBreakdownDTO;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.CandidateWeightedResult;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.GroupCandidateWeightedResult;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.MunicipalitySizeGroup;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.PollGroupBreakdown;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.PollImportResult;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer.PollImportService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.web.servlet.MockMvc;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.BDDMockito.given;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(PollImportController.class)
class PollImportControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private PollImportService pollImportService;

    @MockBean
    private PollImportMapper pollImportMapper;

    @Test
    void shouldImportPollCsvAndReturnWeightedCandidates() throws Exception {
        UUID candidateId = UUID.randomUUID();
        PollImportResult result = new PollImportResult(
                "PESQ-2026-01",
                LocalDate.of(2026, 3, 1),
                1000000L,
                List.of(new CandidateWeightedResult(candidateId, "Maria Silva", new BigDecimal("42.35"))),
                List.of(new PollGroupBreakdown(
                        "SP",
                        MunicipalitySizeGroup.GROUP_4,
                        1_000_000L,
                        500_000L,
                        List.of(new GroupCandidateWeightedResult(candidateId, "Maria Silva", new BigDecimal("42.35")))
                ))
        );
        PollImportResponseDTO response = new PollImportResponseDTO(
                "PESQ-2026-01",
                LocalDate.of(2026, 3, 1),
                1000000L,
                List.of(new CandidateWeightedResultDTO(
                        candidateId,
                        "Maria Silva",
                        new BigDecimal("42.35")
                )),
                List.of(new PollGroupBreakdownDTO(
                        "SP",
                        "GROUP_4",
                        1_000_000L,
                        500_000L,
                        List.of(new GroupCandidateWeightedResultDTO(
                                candidateId,
                                "Maria Silva",
                                new BigDecimal("42.35")
                        ))
                ))
        );

        given(pollImportService.researchImport(any())).willReturn(result);
        given(pollImportMapper.toResponse(result)).willReturn(response);

        MockMultipartFile file = new MockMultipartFile(
                "file",
                "pesquisa.csv",
                "text/csv",
                "poll_id,poll_date,estado,municipio,candidate_id,percentual".getBytes()
        );

        mockMvc.perform(multipart("/api/polls/import").file(file))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.pollId").value("PESQ-2026-01"))
                .andExpect(jsonPath("$.weightedPopulation").value(1000000L))
                .andExpect(jsonPath("$.candidates[0].candidateId").value(candidateId.toString()))
                .andExpect(jsonPath("$.candidates[0].candidateName").value("Maria Silva"))
                .andExpect(jsonPath("$.candidates[0].weightedPercentage").value(42.35))
                .andExpect(jsonPath("$.groupBreakdown[0].stateAcronym").value("SP"))
                .andExpect(jsonPath("$.groupBreakdown[0].municipalityGroup").value("GROUP_4"));
    }
}

package com.diegoramos.konatus.pesquisaeleitoral.service.poll.importer;

import com.diegoramos.konatus.pesquisaeleitoral.domain.Candidate;
import com.diegoramos.konatus.pesquisaeleitoral.domain.Municipality;
import com.diegoramos.konatus.pesquisaeleitoral.domain.State;
import com.diegoramos.konatus.pesquisaeleitoral.repository.CandidateRepository;
import com.diegoramos.konatus.pesquisaeleitoral.repository.MunicipalityRepository;
import com.diegoramos.konatus.pesquisaeleitoral.repository.StateRepository;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest(properties = {
        "spring.datasource.url=jdbc:h2:mem:pollimport;DB_CLOSE_DELAY=-1;MODE=PostgreSQL",
        "spring.datasource.driver-class-name=org.h2.Driver",
        "spring.datasource.username=sa",
        "spring.datasource.password=",
        "spring.jpa.hibernate.ddl-auto=create-drop",
        "spring.flyway.enabled=false"
})
@Transactional
class PollImportServiceIntegrationTest {

    @Autowired
    private PollImportService pollImportService;

    @Autowired
    private StateRepository stateRepository;

    @Autowired
    private MunicipalityRepository municipalityRepository;

    @Autowired
    private CandidateRepository candidateRepository;

    @Test
    void shouldImportCsvAndCalculateWeightedResults() {
        State state = stateRepository.save(State.create("Sao Paulo", "SP"));
        municipalityRepository.save(Municipality.create("Campinas", 1_200_000, state));
        municipalityRepository.save(Municipality.create("Santos", 800_000, state));

        Candidate maria = candidateRepository.save(Candidate.create("Maria Silva", "Partido A"));
        Candidate joao = candidateRepository.save(Candidate.create("Joao Souza", "Partido B"));

        String csv = """
                poll_id,poll_date,estado,municipio,candidate_id,percentual
                PESQ-TESTE-2026,2026-03-10,SP,Campinas,%s,40
                PESQ-TESTE-2026,2026-03-10,SP,Campinas,%s,35
                PESQ-TESTE-2026,2026-03-10,SP,Santos,%s,30
                PESQ-TESTE-2026,2026-03-10,SP,Santos,%s,45
                """.formatted(maria.getId(), joao.getId(), maria.getId(), joao.getId());

        MockMultipartFile file = new MockMultipartFile(
                "file",
                "pesquisa.csv",
                "text/csv",
                csv.getBytes(StandardCharsets.UTF_8)
        );

        PollImportResult result = pollImportService.researchImport(file);

        assertThat(result.pollId()).isEqualTo("PESQ-TESTE-2026");
        assertThat(result.pollDate()).isEqualTo(LocalDate.of(2026, 3, 10));
        assertThat(result.weightedPopulation()).isEqualTo(2_000_000L);

        List<CandidateWeightedResult> candidates = result.weightedCandidateResults();
        assertThat(candidates).hasSize(2);

        assertThat(candidates.getFirst().candidateId()).isEqualTo(joao.getId());
        assertThat(candidates.getFirst().candidateName()).isEqualTo("Joao Souza");
        assertThat(candidates.getFirst().weightedPercentage()).isEqualByComparingTo(new BigDecimal("39.00"));

        assertThat(candidates.get(1).candidateId()).isEqualTo(maria.getId());
        assertThat(candidates.get(1).candidateName()).isEqualTo("Maria Silva");
        assertThat(candidates.get(1).weightedPercentage()).isEqualByComparingTo(new BigDecimal("36.00"));
    }
}

